package ca.yorku.eecs3311.coursepilot.application.agent; import org.springframework.stereotype.Component; import java.util.*; @Component public class TaskPlanner {public AgentPlan plan(AgentIntent intent){return plan(intent,"");}public AgentPlan plan(AgentIntent intent,String request){return switch(intent){case WEAK_TOPIC_SUPPORT->new AgentPlan(intent,List.of(new AgentPlanStep("GET_PROGRESS",Map.of()),new AgentPlanStep("GET_WEAK_TOPICS",Map.of()),new AgentPlanStep("GENERATE_FLASHCARDS",Map.of())));case HISTORY_REVIEW->new AgentPlan(intent,List.of(new AgentPlanStep("GET_HISTORY",Map.of())));case NEXT_STEP->new AgentPlan(intent,List.of(new AgentPlanStep("GET_PROGRESS",Map.of()),new AgentPlanStep("GET_RECOMMENDATION",Map.of())));case COURSE_SEARCH->new AgentPlan(intent,List.of(new AgentPlanStep("COURSE_SEARCH",Map.of("query",Objects.toString(request,"").trim()))));case SUMMARY_GENERATION->new AgentPlan(intent,List.of(new AgentPlanStep("GENERATE_SUMMARY",Map.of())));case QUIZ_GENERATION->new AgentPlan(intent,List.of(new AgentPlanStep("GENERATE_QUIZ",Map.of())));case STUDY_PLAN_CREATION->new AgentPlan(intent,List.of(new AgentPlanStep("CREATE_STUDY_PLAN",Map.of())));case PROGRESS_REVIEW->new AgentPlan(intent,List.of(new AgentPlanStep("GET_PROGRESS",Map.of())));};}}
